-- 0. subjects 테이블에 대단원/모의고사/학원명 컬럼 추가 (없는 경우 자동 생성)
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS academy_name TEXT DEFAULT '';
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS chapters JSONB DEFAULT '[]'::jsonb;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS mock_tests JSONB DEFAULT '[]'::jsonb;

-- 1. subjects 테이블 삽입 (학원명, 대단원 목차 및 모의고사 성적 포함 UPSERT)
ON CONFLICT (name) DO UPDATE SET
  dday = EXCLUDED.dday,
  target_score = EXCLUDED.target_score,
  color = EXCLUDED.color,
  academy_name = EXCLUDED.academy_name,
  chapters = EXCLUDED.chapters,
  mock_tests = EXCLUDED.mock_tests;

-- 2. schedules 테이블 삽입 (UPSERT)
ON CONFLICT (id) DO UPDATE SET date = EXCLUDED.date, category = EXCLUDED.category, subject = EXCLUDED.subject, title = EXCLUDED.title, detail = EXCLUDED.detail, progress = EXCLUDED.progress, score = EXCLUDED.score, duration_sec = EXCLUDED.duration_sec, completed = EXCLUDED.completed;
